from pathlib import Path
import pytest


def first_readable(names: list[str]) -> str:
    """Return the text of the first file in names that can be read from 'notes'.

    Names come from untrusted requests and must resolve strictly inside the
    'notes' directory (relative to the current working directory). Subdirectories
    within 'notes' are allowed. Any path attempting to escape 'notes', or any
    missing or unreadable file, is skipped. If no file can be read, returns an
    empty string.
    """
    notes_dir = Path("notes").resolve()
    for name in names:
        try:
            target = (notes_dir / name).resolve()
            if target == notes_dir or not target.is_relative_to(notes_dir):
                continue
            if not target.is_file():
                continue
            return target.read_text(encoding="utf-8")
        except Exception:
            continue
    return ""


@pytest.fixture
def setup_notes(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    monkeypatch.chdir(tmp_path)
    notes_dir = tmp_path / "notes"
    notes_dir.mkdir()
    return notes_dir


def test_first_readable_simple(setup_notes: Path) -> None:
    (setup_notes / "a.txt").write_text("hello from a", encoding="utf-8")
    (setup_notes / "b.txt").write_text("hello from b", encoding="utf-8")
    assert first_readable(["a.txt", "b.txt"]) == "hello from a"


def test_first_readable_skips_missing(setup_notes: Path) -> None:
    (setup_notes / "b.txt").write_text("hello from b", encoding="utf-8")
    assert first_readable(["missing.txt", "b.txt"]) == "hello from b"


def test_first_readable_nested_subdirectory(setup_notes: Path) -> None:
    sub = setup_notes / "sub"
    sub.mkdir()
    (sub / "nested.txt").write_text("nested content", encoding="utf-8")
    assert first_readable(["sub/nested.txt"]) == "nested content"


def test_first_readable_empty_names(setup_notes: Path) -> None:
    assert first_readable([]) == ""


def test_first_readable_none_exist(setup_notes: Path) -> None:
    assert first_readable(["nope.txt", "sub/nope.txt"]) == ""


def test_first_readable_prevents_path_traversal(
    setup_notes: Path, tmp_path: Path
) -> None:
    outside_file = tmp_path / "secret.txt"
    outside_file.write_text("secret outside", encoding="utf-8")
    (setup_notes / "valid.txt").write_text("valid content", encoding="utf-8")

    assert first_readable(["../secret.txt", "valid.txt"]) == "valid content"
    assert first_readable(["sub/../../secret.txt", "valid.txt"]) == "valid content"
    assert first_readable(["/secret.txt", "valid.txt"]) == "valid content"


def test_first_readable_skips_directory(setup_notes: Path) -> None:
    sub = setup_notes / "sub"
    sub.mkdir()
    (setup_notes / "a.txt").write_text("content", encoding="utf-8")
    assert first_readable(["sub", "a.txt"]) == "content"


def test_first_readable_notes_directory_itself_forbidden(setup_notes: Path) -> None:
    assert first_readable([".", "..", ""]) == ""

